@_command_errors
def alignment_inspect(
    project_dir: Path,
    work_item_id: str,
    version: int,
    input_value: str,
    cursor: str | None,
    limit: int,
) -> None:
    """分页读取判断所需逻辑事实；不暴露或修改缓存布局。"""

    project = _project(project_dir)
