    ) -> list[str]:
        """Expose one candidate authority's exact schema-governed paths."""

        if authority_kind not in AUTHORITY_KINDS:
            raise ProjectAuthorityConsistencyError(
                [f"未知项目权威种类：{authority_kind}"]
            )
        return sorted(
